"use client";

import { Fragment, useEffect, useRef, useState } from "react";
import { useChat } from "@ai-sdk/react";
import {
  JSONUIProvider,
  Renderer,
  buildSpecFromParts,
  useJsonRenderMessage,
} from "@json-render/react";
import { getToolName, isToolUIPart } from "ai";
import { motion } from "motion/react";
import { ChatDevtools } from "@/features/chat/components/chat-devtools";
import { ChatMessage } from "@/components/ui/chat-message";
import { InputMessage } from "@/components/ui/input-message";
import { ScrollArea } from "@/components/ui/scroll-area";
import { catalog } from "@/features/chat/chat-catalog";
import CitedAnswer from "@/features/chat/components/cited-answer";
import { ReplySteps } from "@/features/chat/components/reply-steps";
import { registry } from "@/features/chat/chat-registry";
import { useSize } from "@/lib/size-context";
import { spring } from "@/lib/springs";
import { cn } from "@/lib/utils";
import type { WebSearchProgress } from "@/features/chat/components/reply-steps";
import type { Chat as ChatInstance } from "@ai-sdk/react";
import type { UIMessage } from "ai";

const PINNED_PX = 48;

/**
The element that scrolls inside a Fluid ScrollArea: its ref points at the outer root, and the viewport inside it does the scrolling.
*/
function viewportOf(root: HTMLElement | null) {
  return (
    root?.querySelector<HTMLElement>('[data-slot="scroll-area-viewport"]') ??
    null
  );
}

const SUGGESTIONS = [
  "How's NVDA doing?",
  "Show me Apple over the past year",
  "How did Tesla do this week?",
];

export const Chat = ({
  chat,
  input = true,
  disabled = false,
  placeholder = "Ask about a stock…",
  className,
}: {
  /** An AI SDK chat instance to drive, e.g. one with a custom transport.
   *  Omitted, the chat posts to /api/chat. Give it a fixed id. */
  readonly chat?: ChatInstance<UIMessage>;
  /**
  Show the message composer.
  */
  readonly input?: boolean;
  /**
  Show the composer but don't accept messages (a read-only demo).
  */
  readonly disabled?: boolean;
  readonly placeholder?: string;
  readonly className?: string;
}) => {
  // A fixed id: the AI SDK would otherwise make a random one during render,
  // which a prerender (Cache Components) rejects.
  const { messages, sendMessage, status, stop, error } = useChat(
    chat ? { chat } : { id: "chat" }
  );
  const [draft, setDraft] = useState("");
  const { type } = useSize();

  const scrollReference = useRef<HTMLDivElement>(null);
  const contentReference = useRef<HTMLDivElement>(null);
  const pinnedReference = useRef(true);
  const bottomReference = useRef<HTMLDivElement>(null);
  // Resize observers run before intersection observers in a frame, so growth
  // scrolls first and the marker is still in view when it's checked.
  useEffect(() => {
    const element = viewportOf(scrollReference.current);
    const content = contentReference.current;
    const bottom = bottomReference.current;
    if (!(element && content && bottom)) {
      return;
    }
    const resize = new ResizeObserver(() => {
      if (pinnedReference.current) {
        element.scrollTo({ top: element.scrollHeight });
      }
    });
    const pin = new IntersectionObserver(
      ([entry]) => {
        pinnedReference.current = entry?.isIntersecting ?? true;
      },
      { root: element, rootMargin: `0px 0px ${PINNED_PX}px 0px` }
    );
    resize.observe(content);
    pin.observe(bottom);
    return () => {
      resize.disconnect();
      pin.disconnect();
    };
  }, []);
  useEffect(() => {
    pinnedReference.current = true;
    const element = viewportOf(scrollReference.current);
    element?.scrollTo({ top: element.scrollHeight });
  }, [messages.length]);

  const isBusy = status === "submitted" || status === "streaming";
  const turns = turnsOf(messages);
  const lastId = messages.at(-1)?.id;
  const lastReply = messages.findLast(
    (message) => message.role === "assistant"
  );

  return (
    <JSONUIProvider registry={registry}>
      <ChatDevtools
        spec={lastReply ? buildSpecFromParts(lastReply.parts) : null}
        catalog={catalog}
        messages={messages}
        position="right"
      />
      <div className={cn("flex min-h-0 flex-col", className)}>
        <ScrollArea ref={scrollReference} className="min-h-0 flex-1">
          <div ref={contentReference} className="flex flex-col gap-4 p-4">
            {turns.map((turn, index) => {
              const isLatest = index === turns.length - 1;
              return (
                <Fragment key={turn.id}>
                  {turn.question ? (
                    <ChatMessage from="user">
                      {textOf(turn.question)}
                    </ChatMessage>
                  ) : null}
                  {turn.reply || (isLatest && isBusy) ? (
                    <AssistantMessage
                      message={turn.reply}
                      streaming={
                        isBusy ? !turn.reply || turn.reply.id === lastId : false
                      }
                    />
                  ) : null}
                </Fragment>
              );
            })}
            {error ? (
              <p className={cn(type.caption, "text-muted-foreground")}>
                Something went wrong. Send the message again.
              </p>
            ) : null}
            <div ref={bottomReference} aria-hidden className="-mt-4 h-px" />
          </div>
        </ScrollArea>

        {input ? (
          <div className="p-3 pt-0">
            <InputMessage
              value={draft}
              onValueChange={setDraft}
              onSend={(text) => {
                if (!text) {
                  return;
                }

                sendMessage({ text });
                setDraft("");
              }}
              status={isBusy ? "streaming" : "idle"}
              onStop={stop}
              disabled={disabled}
              placeholder={placeholder}
              suggestions={
                messages.length === 0 && !disabled ? SUGGESTIONS : undefined
              }
            />
          </div>
        ) : null}
      </div>
    </JSONUIProvider>
  );
};

interface Turn {
  id: string;
  question?: UIMessage;
  reply?: UIMessage;
}

function turnsOf(messages: readonly UIMessage[]): Turn[] {
  const turns: Turn[] = [];
  for (const message of messages) {
    const last = turns.at(-1);
    if (message.role === "user") {
      turns.push({ id: message.id, question: message });
    } else if (last && !last.reply) {
      last.reply = message;
    } else {
      turns.push({ id: message.id, reply: message });
    }
  }
  return turns;
}

const NO_PARTS: UIMessage["parts"] = [];

function queriesOf(input: unknown): string[] {
  const queries =
    typeof input === "object" && input !== null && "queries" in input
      ? input.queries
      : undefined;
  return Array.isArray(queries)
    ? queries.filter((query): query is string => typeof query === "string")
    : [];
}

function webSearchOf(parts: UIMessage["parts"]): WebSearchProgress | null {
  const queries: string[] = [];
  const sources: { id: string; title: string; url: string }[] = [];
  let calls = 0;
  let isDone = true;
  for (const part of parts) {
    if (part.type === "source-url") {
      sources.push({
        id: part.sourceId,
        title: part.title ?? part.url,
        url: part.url,
      });
    } else if (isToolUIPart(part) && getToolName(part) === "webSearch") {
      calls += 1;
      queries.push(...queriesOf(part.input));
      isDone &&=
        part.state === "output-available" || part.state === "output-error";
    }
  }
  return calls > 0 ? { isDone, queries, sources } : null;
}

const AssistantMessage = ({
  message,
  streaming,
}: {
  readonly message?: UIMessage;
  readonly streaming: boolean;
}) => {
  const parts = message?.parts ?? NO_PARTS;
  const { spec, text } = useJsonRenderMessage(parts);
  const [isAnswerShown, setIsAnswerShown] = useState(false);
  const search = webSearchOf(parts);
  const isShown = isAnswerShown || (!spec && text.length > 0);
  return (
    <div className="flex flex-col gap-3">
      <ReplySteps
        spec={spec}
        hasText={text.length > 0}
        search={search}
        streaming={streaming}
        onFinish={() => setIsAnswerShown(true)}
      />
      {isShown ? (
        <motion.div
          className="flex flex-col gap-3"
          initial={{ opacity: 0, y: 6 }}
          animate={{ opacity: 1, y: 0 }}
          transition={spring.slow}
        >
          {text && search ? (
            <CitedAnswer
              text={text}
              sources={search.sources}
              isComplete={!streaming}
            />
          ) : null}
          {text && !search ? (
            <ChatMessage from="assistant">{text}</ChatMessage>
          ) : null}
          {spec ? (
            <Renderer spec={spec} registry={registry} loading={streaming} />
          ) : null}
        </motion.div>
      ) : null}
    </div>
  );
};

function textOf(message: UIMessage) {
  return message.parts
    .map((part) => (part.type === "text" ? part.text : ""))
    .join("");
}

import { z } from "zod";
import { cn } from "@/lib/utils";
import type { ReactNode } from "react";

export const CardGroup = ({
  children,
  className,
}: {
  readonly children?: ReactNode;
  readonly className?: string;
}) => (
  <div className={cn("@container w-full", className)}>
    <div className="grid grid-cols-1 items-start gap-3 @2xl:grid-cols-2">
      {children}
    </div>
  </div>
);

export const cardGroupCatalogEntry = {
  description:
    "Holds several cards in one reply. Use it as the root whenever the reply shows more than one card, with one card per child.",
  props: z.object({}),
  slots: ["default"],
};

"use client";

import dynamic from "next/dynamic";

// json-render's devtools panel, in development only. Behind a dynamic import
// on NODE_ENV, so production builds don't ship its code at all (on its own
// it renders null in production but still lands in the bundle).
export const ChatDevtools =
  process.env.NODE_ENV === "development"
    ? dynamic(
        () =>
          import("@json-render/devtools-react").then(
            (module) => module.JsonRenderDevtools
          ),
        { ssr: false }
      )
    : () => null;

"use client";

import { useEffect, useRef, useState } from "react";
import {
  ThinkingStep,
  ThinkingStepDetails,
  ThinkingSteps,
  ThinkingStepsContent,
  ThinkingStepsHeader,
} from "@/components/ui/thinking-steps";
import { lookups } from "@/features/chat/chat-steps";
import { listOf } from "@/features/chat/lookup";
import { spring } from "@/lib/springs";
import { hostOf } from "@/lib/url-host";
import type { CardLookup, Source } from "@/features/chat/lookup";
import type { Spec } from "@json-render/core";
import type { IconName } from "@/lib/icon-context";
import type { ReactNode } from "react";

const DONE_HOLD_MS = 600;
const READ_BEAT_MS = 400;
const FOLD_MS = Math.round(spring.moderate.duration * 1000);

type Load =
  | { status: "loading" }
  | { status: "ready"; sources: readonly Source[] }
  | { status: "error"; message: string };

interface Card {
  key: string;
  subject: string;
  lookup: CardLookup;
  props: Record<string, unknown>;
}

interface Step {
  key: string;
  icon: IconName;
  label: string;
  done: boolean;
  children?: ReactNode;
}

type StepStatus = "complete" | "active" | "pending";

/**
The reply's web searches, for the search step.
*/
export interface WebSearchProgress {
  readonly queries: readonly string[];
  readonly isDone: boolean;
  readonly sources: readonly { id: string; title: string; url: string }[];
}

function cardsIn(spec: Spec | null): Card[] {
  const cards: Card[] = [];
  const elements = Object.values(spec?.elements ?? {});
  for (const element of elements) {
    const lookup = lookups[element.type];
    const properties = (element.props ?? {}) as Record<string, unknown>;
    const subject = lookup?.subject(properties);
    if (lookup && subject) {
      cards.push({
        key: `${element.type}:${subject}`,
        lookup,
        props: properties,
        subject,
      });
    }
  }
  return cards;
}

function areSameCards(left: readonly Card[], right: readonly Card[]): boolean {
  return (
    left.length === right.length &&
    left.every((card, index) => card.key === right[index]?.key)
  );
}

function useLoads(cards: readonly Card[], isReady: boolean) {
  const [loads, setLoads] = useState<Record<string, Load>>({});
  const [plan, setPlan] = useState({ cards, isReady });
  if (plan.isReady !== isReady || !areSameCards(plan.cards, cards)) {
    setPlan({ cards, isReady });
  }

  useEffect(() => {
    let isCancelled = false;
    const toLoad = plan.isReady ? plan.cards : [];
    for (const card of toLoad) {
      const settle = (load: Load) => {
        if (!isCancelled) {
          setLoads((current) => ({ ...current, [card.key]: load }));
        }
      };
      card.lookup
        .load(card.props)
        .then((result) =>
          settle({
            sources: card.lookup.resultSources?.(result) ?? [],
            status: "ready",
          })
        )
        .catch((error: unknown) =>
          settle({
            message: Error.isError(error) ? error.message : "It failed.",
            status: "error",
          })
        );
    }
    return () => {
      isCancelled = true;
    };
  }, [plan]);

  return loads;
}

/**
Whether the read beat has passed: a short hold once the sources are in, so "Read N sources" lands as its own step instead of flashing by. Disarming resets it.
*/
function useHasReadBeatElapsed(isArmed: boolean): boolean {
  const [hasElapsed, setHasElapsed] = useState(false);
  if (!isArmed && hasElapsed) {
    setHasElapsed(false);
  }
  useEffect(() => {
    const beat = setTimeout(() => {
      if (isArmed) {
        setHasElapsed(true);
      }
    }, READ_BEAT_MS);
    return () => clearTimeout(beat);
  }, [isArmed]);
  return hasElapsed;
}

function uniqueHosts(sources: readonly Source[]): Source[] {
  const byHost = new Map<string, Source>();
  for (const source of sources) {
    const host = hostOf(source.href) || source.label;
    if (!byHost.has(host)) {
      byHost.set(host, { href: source.href, label: host });
    }
  }
  return [...byHost.values()];
}

function pickSources(
  researched: readonly Source[],
  fromSearch: readonly Source[],
  cards: readonly Card[]
): Source[] {
  if (researched.length > 0) {
    return [...researched];
  }
  return fromSearch.length > 0
    ? [...fromSearch]
    : uniqueHosts(cards.flatMap((card) => card.lookup.sources(card.props)));
}

function sourceLabel(count: number, verb: "Read" | "Explored"): string {
  const noun = count === 1 ? "source" : "sources";
  return `${verb} ${count} ${noun}`;
}

function buildSteps({
  isResearching,
  isSearched,
  isRead,
  isDone,
  cards,
  sources,
}: {
  isResearching: boolean;
  isSearched: boolean;
  isRead: boolean;
  isDone: boolean;
  cards: readonly Card[];
  sources: readonly Source[];
}): Step[] {
  if (!isResearching) {
    if (!isDone) {
      return [];
    }
    return [
      {
        done: true,
        icon: "check",
        key: "done",
        label: "Done",
      },
    ];
  }

  return [
    {
      done: isSearched,
      icon: "search",
      key: "search",
      label:
        cards.length > 0
          ? `Looking up ${listOf(cards.map((card) => card.subject))}`
          : "Searched the web",
    },
    {
      children:
        isRead && sources.length > 0 ? (
          <ThinkingStepDetails
            summary={sourceLabel(sources.length, "Explored")}
            details={sources.map((source) => `Read ${source.label}`)}
          />
        ) : undefined,
      done: isRead,
      icon: "globe",
      key: "read",
      label:
        sources.length > 0
          ? sourceLabel(sources.length, "Read")
          : "Reading sources",
    },
    {
      done: isDone,
      icon: "check",
      key: "done",
      label: "Done",
    },
  ];
}

function stepStatus(active: number, index: number): StepStatus {
  if (active === -1 || index < active) {
    return "complete";
  }
  return index === active ? "active" : "pending";
}

/**
Basic ThinkingSteps: Searched → Read N sources → Done.
Card stays last — onFinish runs only after Done.
*/
export function ReplySteps({
  spec,
  hasText,
  search = null,
  streaming,
  onFinish,
}: {
  readonly spec: Spec | null;
  readonly hasText: boolean;
  readonly search?: WebSearchProgress | null;
  readonly streaming: boolean;
  readonly onFinish: () => void;
}) {
  const cards = cardsIn(spec);
  const loads = useLoads(cards, !streaming);
  const [open, setOpen] = useState(true);
  const [startedAt] = useState(() => performance.now());
  /**
  Seconds from the first render to Done, set when the steps fold; null until then.
  */
  const [foldedAfter, setFoldedAfter] = useState<number | null>(null);

  const isStarted = hasText || spec !== null || search !== null;
  const isWritten = isStarted && !streaming;
  const isFetched = cards.every((card) => {
    const load = loads[card.key];
    return load && load.status !== "loading";
  });
  const isSearched =
    (search ? search.isDone : true) && (cards.length === 0 || isFetched);
  const isResearching = Boolean(search) || cards.length > 0;
  const canMarkRead = isStarted && isSearched;
  const hasBeatElapsed = useHasReadBeatElapsed(canMarkRead && isResearching);

  const isRead = canMarkRead && (!isResearching || hasBeatElapsed);
  const isDone = isWritten && isSearched && isRead;

  const onFinishReference = useRef(onFinish);
  onFinishReference.current = onFinish;
  useEffect(() => {
    // Read once Done lands, so the hold before the fold isn't counted.
    const doneAt = performance.now();
    const fold = setTimeout(() => {
      if (!isDone) {
        return;
      }
      setFoldedAfter((doneAt - startedAt) / 1000);
      setOpen(false);
    }, DONE_HOLD_MS);
    const finish = setTimeout(() => {
      if (isDone) {
        onFinishReference.current();
      }
    }, DONE_HOLD_MS + FOLD_MS);
    return () => {
      clearTimeout(fold);
      clearTimeout(finish);
    };
  }, [isDone, startedAt]);

  if (!isStarted) {
    return null;
  }

  const researched = uniqueHosts(
    cards.flatMap((card) => {
      const load = loads[card.key];
      return load?.status === "ready" ? load.sources : [];
    })
  );
  const fromSearch = search
    ? uniqueHosts(
        search.sources.map(({ url }) => ({
          href: url,
          label: hostOf(url),
        }))
      )
    : [];
  const sources = pickSources(researched, fromSearch, cards);
  const steps = buildSteps({
    cards,
    isDone,
    isRead,
    isResearching,
    isSearched,
    sources,
  });
  const active = steps.findIndex((step) => !step.done);
  const lastShown = active === -1 ? steps.length - 1 : active;

  return (
    <ThinkingSteps open={open} onOpenChange={setOpen}>
      <ThinkingStepsHeader>
        {foldedAfter === null
          ? "Thinking"
          : `Worked for ${foldedAfter.toFixed(1)}s`}
      </ThinkingStepsHeader>
      {steps.length > 0 ? (
        <ThinkingStepsContent>
          {steps.map((step, index) => {
            const status = stepStatus(active, index);
            return (
              <ThinkingStep
                key={step.key}
                icon={step.icon}
                label={step.label}
                status={status}
                isLast={index === lastShown}
              >
                {status === "complete" ? step.children : undefined}
              </ThinkingStep>
            );
          })}
        </ThinkingStepsContent>
      ) : null}
    </ThinkingSteps>
  );
}

"use client";

import { ChatMessage } from "@/components/ui/chat-message";
import { useSize } from "@/lib/size-context";
import { hostOf } from "@/lib/url-host";
import { cn } from "@/lib/utils";
import type { ReactNode } from "react";

interface CitedSource {
  readonly id: string;
  readonly title: string;
  readonly url: string;
}

const CITATION = /\[\d+\]/gu;
const REFERENCE_LINE = /^\s*\[\d+\]\s+\S/u;

function withoutReferenceList(text: string): string {
  return text
    .split("\n")
    .filter((line) => !REFERENCE_LINE.test(line))
    .join("\n")
    .trimEnd();
}

function idOf(marker: string): string {
  return marker.slice(1, -1);
}

function Citation({ source }: { readonly source: CitedSource }) {
  return (
    <a
      href={source.url}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={`Source ${source.id}: ${source.title} (opens in a new tab)`}
      className="bg-muted text-muted-foreground hover:text-foreground focus-visible:ring-ring mx-0.5 inline-flex min-w-4 -translate-y-px items-center justify-center rounded px-1 align-baseline text-[0.7em] leading-4 font-medium tabular-nums no-underline outline-none focus-visible:ring-2"
    >
      {source.id}
    </a>
  );
}

function withCitations(
  text: string,
  byId: ReadonlyMap<string, CitedSource>
): ReactNode[] {
  const nodes: ReactNode[] = [];
  let offset = 0;
  for (const match of text.matchAll(CITATION)) {
    const source = byId.get(idOf(match[0]));
    if (!source) {
      continue;
    }
    nodes.push(
      text.slice(offset, match.index),
      <Citation key={match.index} source={source} />
    );
    offset = match.index + match[0].length;
  }
  nodes.push(text.slice(offset));
  return nodes;
}

export default function CitedAnswer({
  text: written,
  sources,
  isComplete,
}: {
  readonly text: string;
  readonly sources: readonly CitedSource[];
  readonly isComplete: boolean;
}) {
  const { type } = useSize();
  const text = withoutReferenceList(written);
  const byId = new Map(sources.map((source) => [source.id, source]));
  const citedIds = new Set(
    Array.from(text.matchAll(CITATION), (match) => idOf(match[0]))
  );
  const cited = sources.filter((source) => citedIds.has(source.id));

  return (
    <>
      <ChatMessage from="assistant">{withCitations(text, byId)}</ChatMessage>
      {isComplete && cited.length > 0 ? (
        <section aria-label="Sources" className="flex flex-col gap-1.5">
          <h3 className={cn(type.caption, "text-muted-foreground font-medium")}>
            Sources
          </h3>
          <ol className="flex flex-col gap-1">
            {cited.map((source) => (
              <li key={source.id} className={cn(type.caption, "flex gap-2")}>
                <span className="text-muted-foreground w-4 shrink-0 text-right tabular-nums">
                  {source.id}
                </span>
                <a
                  href={source.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="focus-visible:ring-ring min-w-0 rounded outline-none hover:underline hover:underline-offset-2 focus-visible:ring-2"
                >
                  <span className="text-foreground">{source.title}</span>
                  <span className="text-muted-foreground">
                    {" "}
                    · {hostOf(source.url)}
                  </span>
                  <span className="sr-only"> (opens in a new tab)</span>
                </a>
              </li>
            ))}
          </ol>
        </section>
      ) : null}
    </>
  );
}

import "server-only";
import { createSearchTool } from "@parallel-web/ai-sdk-tools";
import { tool } from "ai";
import { z } from "zod";
import { hostOf } from "@/lib/url-host";

const MAX_RESULTS = 6;
const MAX_EXCERPT_CHARS = 4000;

export interface WebSearchSource {
  readonly id: number;
  readonly title: string;
  readonly url: string;
  readonly published: string | null;
  readonly excerpts: readonly string[];
}

export interface WebSearchOutput {
  readonly results: readonly WebSearchSource[];
}

interface RawResult {
  readonly url: string;
  readonly title?: string | null;
  readonly excerpts?: readonly string[];
  readonly publish_date?: string | null;
}

function hasResults<RESULT>(value: unknown): value is { results: RESULT[] } {
  return (
    typeof value === "object" &&
    value !== null &&
    "results" in value &&
    Array.isArray(value.results)
  );
}

export function isWebSearchOutput(value: unknown): value is WebSearchOutput {
  return hasResults<WebSearchSource>(value);
}

export function createWebSearch(model: string) {
  const search = createSearchTool({
    client_model: model,
    max_results: MAX_RESULTS,
    mode: "basic",
  });
  let nextId = 1;

  return tool({
    description:
      "Search the web for facts no card covers: history, how-many and who/why questions, recent events. Returns numbered results; cite them as [n].",
    execute: async ({ objective, queries }, options) => {
      const response = await search.execute?.(
        { objective, search_queries: queries },
        options
      );
      if (!hasResults<RawResult>(response)) {
        throw new Error("The web search returned nothing.");
      }
      const firstId = nextId;
      nextId += response.results.length;
      const results = response.results.map(
        (result, index): WebSearchSource => ({
          excerpts: (result.excerpts ?? []).map((excerpt) =>
            excerpt.slice(0, MAX_EXCERPT_CHARS)
          ),
          id: firstId + index,
          published: result.publish_date ?? null,
          title: result.title?.trim() || hostOf(result.url),
          url: result.url,
        })
      );
      return { results } satisfies WebSearchOutput;
    },
    inputSchema: z.object({
      objective: z
        .string()
        .describe("What the answer needs, in one sentence, for ranking."),
      queries: z
        .array(z.string())
        .min(1)
        .max(3)
        .describe("1–3 short keyword queries."),
    }),
  });
}

export function hostOf(url: string): string {
  try {
    const { hostname } = new URL(url);
    return hostname.replace(/^www\./u, "");
  } catch {
    return url;
  }
}

/**
Where a card's data comes from, for the "Read N sources" step.
*/
export interface Source {
  /**
  Host or short name, e.g. "finance.yahoo.com".
  */
  label: string;
  href: string;
}

export interface CardLookup {
  /**
  What the question asked for, given the cards' subjects — e.g. "A stock quote for NVDA".
  */
  intent: (subjects: readonly string[]) => string;
  /**
  What one card is about, e.g. "London" or "NVDA"; null while the props aren't usable yet.
  */
  subject: (properties: Record<string, unknown>) => string | null;
  /** The card's own request for these props (shared, so the card reuses it
   *  when it mounts instead of fetching again). */
  load: (properties: Record<string, unknown>) => Promise<unknown>;
  /**
  Known source(s) for this card (Yahoo, ESPN, …). Used in "Read N sources"
  when the load doesn't discover a more specific page.
  */
  sources: (properties: Record<string, unknown>) => readonly Source[];
  /**
  Sources discovered only after the card's request lands (e.g. Parallel's
  extracted page). Wins over `sources` when present.
  */
  resultSources?: (result: unknown) => readonly Source[];
}

/**
"London", "London and Paris", "London, Paris and Tokyo".
*/
export function listOf(items: readonly string[]) {
  return items.length <= 1
    ? (items[0] ?? "")
    : `${items.slice(0, -1).join(", ")} and ${items.at(-1)}`;
}

